export function getBlogArticle(slug) {
  return BLOG_ARTICLES.find(a => a.slug === slug) || null;
}

export function getRelatedArticles(slugs) {
  return slugs.map(s => BLOG_ARTICLES.find(a => a.slug === s)).filter(Boolean);
}
